    // transfer beat needs no second table: Na -> Na+, Cl -> Cl-.
    var BS_ION_OF = (function () {
        var o = {}, k;
        for (k in BS_ION_PARENT) if (BS_ION_PARENT.hasOwnProperty(k)) o[BS_ION_PARENT[k]] = k;
        return o;
    })();
