        // Accumulator-free: every value INCLUDING the spin angle and the dot
        // count is a pure fn of state-local t (Rule 26/36).
        pmStepAnnotations();

        if (config.scenario_type === "orbital_shapes") {
            var osStateDef = config.states[PM_currentState];
            if (osStateDef) { updateOrbitalShapesFrame(osStateDef); applyOrbitalShapesGlow(osStateDef); }
        }

        // dipole_potential — timed reveals, STATE_3/5 sweeps, signed-V recolor
        // readout, V-vs-θ + V-vs-1/r² graph panels, STATE_7 drag (pure state clock).
        if (config.scenario_type === "dipole_potential") {
            var dpStateDef = config.states[PM_currentState];
            if (dpStateDef) updateDipolePotentialFrame(dpStateDef);
        }

        // system_of_charges — timed reveals (per-charge tags, running sum, far-term
        // highlight, pair cancellation, field contrast), STATE_6 idle sweep + drag,
        // and the live signed-V sums (pure fn of the state clock, Rule 26).
        if (config.scenario_type === "system_of_charges") {
            var socStateDef = config.states[PM_currentState];
            if (socStateDef) updateSystemOfChargesFrame(socStateDef);
        }

        // system_pe_assembly — charge fly-ins (eased, pure clock), pair-bond + U-tag
        // reveals, signed energy meter fill, live pair sums, STATE_6 drag (Rule 26).
        if (config.scenario_type === "system_pe_assembly") {
            var peStateDef2 = config.states[PM_currentState];
            if (peStateDef2) updateSystemPeAssemblyFrame(peStateDef2);
        }

