        if (config.scenario_type === "galvanometer_to_ammeter_voltmeter") {
            updateGalvanometerAmmeterVoltmeterFrame();
            applyGalvanometerAmmeterVoltmeterGlow();
        }

        // bar_magnet_as_dipole — field-tracer stream + loop trace / break / probe
        // r-sweep beats (pure fn of the state clock, Rule 26) + TTS glow.
        if (config.scenario_type === "bar_magnet_as_dipole") {
            updateBarMagnetAsDipoleFrame();
            applyBarMagnetAsDipoleGlow();
        }

        // Electric dipole in a uniform field — rotation + τ scaling + couple-
        // arrow repositioning + θ-arc + U-meter + TTS glow.
        if (config.scenario_type === "dipole_in_uniform_field" ||
            config.scenario_type === "bar_magnet_in_uniform_field") {
            updateDipoleInFieldFrame(heldAtPin ? 0 : dtStep);
            applyDipoleInFieldGlow();
        }

        // electric_flux — open-mode tilt sweep + lines-through tally + signed Φ,
        // or closed-mode face accumulation + charge sweep + net-flux tally. Pure
        // function of the state clock (time - stateStartTime), Rule 26.
        if (config.scenario_type === "electric_flux") {
            updateElectricFluxFrame();
        }

        // gauss_law — Gaussian-surface morph (sphere→cube→blob) + signed-pair
        // drag + enclosed-charge sweep + live Φ = q_enc/ε₀ readout. Pure
        // function of the state clock (time - stateStartTime), Rule 26.
        if (config.scenario_type === "gauss_law") {
            updateGaussLawFrame();
        }

        // gauss_law_magnetism — closed-loop tracer stream + S4 surface morph +
        // S6 sandbox drag + Φ_B = 0 readout (state clock, Rule 26) + TTS glow.
        if (config.scenario_type === "gauss_law_magnetism") {
            updateGaussLawMagnetismFrame();
            applyGaussLawMagnetismGlow();
        }

        // earths_magnetism — dip-needle tilt + D/I arcs + H/V/B triangle + live
        // readout (pure fn of the state clock, Rule 26) + TTS glow.
        if (config.scenario_type === "earths_magnetism") {
            updateEarthsMagnetismFrame();
            applyEarthsMagnetismGlow();
        }

        // magnetisation — dipole alignment + M growth + dense-line fade + current
        // pulse + H/M/B/mu_r readout (pure fn of the state clock, Rule 26) + glow.
        if (config.scenario_type === "magnetisation") {
            updateMagnetisationFrame();
            applyMagnetisationGlow();
        }

        // faraday — magnet slide/oscillation + flux-opacity + needle deflection +
        // current-arrow flip + Lenz push arrow + Phi/eps readout (pure fn of the state
        // clock, Rule 26) + TTS glow. OWN block (never nested in another scenario's).
        if (config.scenario_type === "faraday") {
            updateFaradayFrame();
            applyFaradayGlow();
        }

        // motional_emf_rod — eps = B v l via q v x B. Drives the rod slide
        // (independent choreography pace), the live eps/I/F_retard/F_ext/P
        // readout (a pure fn of the B/l/v/R/v_dir sliders), the charge-
        // separation markers + internal E arrow, the RHR hand's 3-phase curl
        // (v -> curl-to-B -> F) with a re-curl on a v_dir flip, the current
